import{_ as t,o as s,c as i,a4 as a}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0041 — Médiathèque, lot 1 : un fonds par organisation, des octets immuables, des références vérifiées","description":"Extrait de docs/adr/0041-mediatheque-socle.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0041 — Médiathèque, lot 1 : un fonds par organisation, des octets immuables, des références vérifiées","description":"Extrait de docs/adr/0041-mediatheque-socle.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0041-mediatheque-socle.md","filePath":"developpeurs/adr/0041-mediatheque-socle.md"}'),n={name:"developpeurs/adr/0041-mediatheque-socle.md"};function o(r,e,d,l,c,u){return s(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0041--médiathèque-lot-1--un-fonds-par-organisation-des-octets-immuables-des-références-vérifiées" tabindex="-1">ADR-0041 — Médiathèque, lot 1 : un fonds par organisation, des octets immuables, des références vérifiées <a class="header-anchor" href="#adr-0041--médiathèque-lot-1--un-fonds-par-organisation-des-octets-immuables-des-références-vérifiées" aria-label="Permalink to &quot;ADR-0041 — Médiathèque, lot 1 : un fonds par organisation, des octets immuables, des références vérifiées {#adr-0041--médiathèque-lot-1--un-fonds-par-organisation-des-octets-immuables-des-références-vérifiées}&quot;">​</a></h1><p><strong>Date :</strong> 23 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §3.2, §9.3, §11.1, §12 ; audit du 10/09/2026, constat P1 n°4 (dernier bloquant ouvert) ; audit SEO du 18/09/2026, constat S12 ; clôt l&#39;action « médiathèque » de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0017-fichiers-personnels-adresses-par-identifiant">ADR-0017</a>, s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0025-multilinguisme-groupe-de-traduction">ADR-0025</a>, l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a>, l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0031-limitation-de-debit">ADR-0031</a>, l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0035-plan-de-site-flux-et-robots">ADR-0035</a> et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0038-pieces-jointes-des-formulaires-publics">ADR-0038</a><strong>Renvois ultérieurs :</strong> « Négatives » (dépôt lu en mémoire) amendées par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0044-video-depot-en-flux-et-sous-titres">ADR-0044</a> (23 septembre 2026) ; décision n°4 (« aucune miniature ») remise en question par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0049-identite-visuelle-du-site-public">ADR-0049</a> (24 septembre 2026), qui ouvre l&#39;action de trancher les déclinaisons d&#39;images par largeur — la décision reste en vigueur tant qu&#39;une ADR ne l&#39;a pas amendée.</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Un champ <code>media</code>, <code>media_gallery</code>, <code>file</code> ou <code>audio</code> n&#39;était qu&#39;une <strong>saisie d&#39;UUID</strong> : aucune table ne disait ce que cet identifiant désignait. Un identifiant inventé passait pour une image, aucune alternative textuelle n&#39;accompagnait un visuel, et rien n&#39;empêchait de citer dans un article un média qui n&#39;existait pas. Le bloc <code>MediaBlock</code> et l&#39;image d&#39;une page portaient le même trou. C&#39;était le dernier bloquant P1 de l&#39;audit du 10/09.</p><p>L&#39;ADR-0038 en avait levé la conséquence la plus grave (un CV exigé qu&#39;aucune route ne permettait de déposer), en donnant aux formulaires publics leurs pièces jointes. Mais une pièce jointe est un fichier <strong>lié à une personne</strong> : elle passe par le mécanisme de l&#39;ADR-0017. Un visuel d&#39;article, lui, n&#39;est lié à personne. L&#39;ADR-0017 le disait dans son action : réutiliser ce mécanisme pour les fichiers liés à une personne, <strong>et seulement pour ceux-là</strong>.</p><p>Le Product Owner a découpé le chantier en deux lots. Le <strong>lot 1</strong>, objet de cette ADR, est le socle : table, dépôt, métadonnées, routes, validation des références. L&#39;écran Médiathèque et le sélecteur visuel du back-office sont menés en parallèle, contre le même contrat d&#39;API. Le <strong>lot 2</strong> branche la médiathèque sur le reste du CMS.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. La médiathèque appartient à l&#39;organisation, pas au site.</strong> La table <code>media_assets</code> (migration <code>0034</code>) porte un média par ligne, rattachée à l&#39;organisation (<code>ON DELETE CASCADE</code>). Tous les sites d&#39;une collectivité la partagent, comme le modèle de site le déclarait déjà (<code>share: [media_library]</code>, CDC §9.3). C&#39;est aussi ce qui rend sûre la réplication d&#39;un contenu ou d&#39;une page entre deux sites : l&#39;identifiant reste valable des deux côtés.</p><p><strong>2. Le média porte ses propres métadonnées</strong> (CDC §11.1).</p><ul><li><code>alt_text</code> et <code>caption</code> sont la valeur de référence. <code>translations</code> porte les autres langues, <code>{locale: {alt_text, caption}}</code>, avec le validateur de langue du Core. C&#39;est le parti de <code>TaxonomyTerm.labels</code> (ADR-0025) : une ligne dont les textes varient.</li><li><code>is_decorative</code> marque l&#39;alternative <strong>vide voulue</strong> (RGAA 1.2). Une image décorative n&#39;a pas d&#39;alternative, ni de référence ni traduite : la marque les vide, et elles restent vides tant qu&#39;elle est posée.</li><li><code>missing_alt</code> est calculé : une image non décorative sans alternative. C&#39;est la liste de travail d&#39;un référent accessibilité (<code>GET /media?missing_alt=true</code>).</li><li><code>copyright</code> est un champ de premier rang, non traduit.</li></ul><p><strong>3. Le type est décidé au dépôt, par le contenu.</strong> <code>POST /api/v1/media</code> lit son corps par l&#39;analyseur borné de l&#39;ADR-0038 (<code>app/core/multipart.py</code>). Les contrôles vont du moins coûteux au plus coûteux, et rien n&#39;est écrit avant le dernier :</p><ul><li>l&#39;extension, parmi les formats acceptés (images jpg, jpeg, png, gif, webp, svg ; documents pdf, doc, xls, ppt, docx, xlsx, pptx, odt, ods, odp, txt, csv ; sons mp3, wav, ogg, oga, opus, m4a, flac) ;</li><li>le fichier vide, puis la taille (<code>MEDIA_UPLOAD_MAX_MB</code>, 50 par défaut, entre 1 et 500), opposée à la longueur annoncée puis au flux ;</li><li>le <strong>type réel</strong>, reconnu aux premiers octets par <strong>la même table</strong> que les pièces jointes (<code>KNOWN_KINDS</code>) ;</li><li>les dimensions, lues dans l&#39;en-tête ;</li><li>l&#39;antivirus, s&#39;il est configuré. Injoignable, il fait refuser le dépôt (503), jamais l&#39;accepter.</li></ul><p>Les refus sont des erreurs rattachées au champ <code>file</code>, avec les codes des pièces jointes (<code>file.type</code>, <code>file.content_mismatch</code>, <code>file.empty</code>, <code>file.too_large</code>, <code>file.infected</code>). Pas de vidéo au lot 1 : la servir demande les requêtes <code>Range</code>.</p><p><strong>4. Aucune miniature, aucune dépendance.</strong> L&#39;original est gardé seul. Ses dimensions sont lues dans l&#39;en-tête (PNG, GIF, JPEG, WebP, SVG), et valent <code>NULL</code> si elles sont illisibles. Le redimensionnement revient au front ou à un proxy d&#39;image.</p><p><strong>5. Le SVG est accepté, et toujours isolé.</strong></p><ul><li>Il est reconnu au texte : du UTF-8 dont l&#39;élément racine est <code>&lt;svg</code>, après le prologue. Un SVG qui déclare une entité (<code>&lt;!ENTITY</code>) ou un sous-ensemble DTD interne est <strong>refusé</strong>. Le Core ne parse pas le SVG : il n&#39;a pas <code>defusedxml</code>, et <code>xml.etree</code> n&#39;est pas sûr face à ces constructions.</li><li>Il est toujours servi avec <code>Content-Security-Policy: sandbox; default-src &#39;none&#39;; style-src &#39;unsafe-inline&#39;</code>. Ouvert directement, un SVG est un document qui peut porter du script : la politique lui retire script, requêtes sortantes et origine.</li><li>Il est réservé à la médiathèque (<code>MEDIA_LIBRARY_ONLY_EXTENSIONS</code>). Une pièce jointe de formulaire public s&#39;ouvre sur le poste d&#39;un agent, hors de toute isolation : le SVG en reste exclu, quoi qu&#39;un formulaire déclare.</li></ul><p><strong>6. Un dépôt d&#39;octets distinct, adressé par identifiant.</strong> <code>app/storage/media_files.py</code> reprend les verrous de l&#39;ADR-0017 : clé dérivée des identifiants, aucune méthode d&#39;énumération, clé validée avant tout accès disque. Il a sa propre racine (<code>MEDIA_ROOT</code>, <code>var/media</code> par défaut), que le démarrage refuse de confondre avec celle des fichiers personnels. Il relit <strong>en flux</strong>, par morceaux : l&#39;ADR-0017 notait qu&#39;une médiathèque devrait le faire. Les octets sont <strong>immuables</strong> : remplacer un fichier, c&#39;est déposer un nouveau média.</p><p><strong>7. Les références sont vérifiées à l&#39;écriture.</strong></p><ul><li>Une valeur de champ média d&#39;un enregistrement doit désigner un média de l&#39;organisation, y compris dans un répéteur. De même pour <code>MediaBlock.media_ids</code> et les champs média des blocs de plugin d&#39;une page, zones imbriquées comprises.</li><li>Sinon 422, une erreur par champ : « ce média n&#39;existe pas dans la médiathèque ». Au format Pydantic pour un enregistrement, en phrase préfixée du chemin du bloc pour une page. Les identifiants sont vérifiés par lot, en une requête.</li><li><strong>Dualité des champs fichier.</strong> Un enregistrement existant accepte aussi les pièces jointes des demandes dont il est le dossier (<code>form_submissions.entry_id</code>, ADR-0038). Sans cela, un agent ne pourrait plus corriger un dossier sans perdre le CV qui y est joint. Les soumissions publiques ne changent pas.</li></ul><p><strong>8. Un média cité ne se supprime pas.</strong> <code>DELETE /media/{id}</code> rend 409 avec la liste des usages tant qu&#39;un contenu le cite. Sinon, il efface les octets <strong>puis</strong> la ligne. Les usages sont trouvés en cherchant la chaîne de l&#39;UUID dans le JSONB converti en texte, borné à l&#39;organisation. Sont lus <code>content_entries.data</code> et <code>settings</code>, <code>pages.layout</code> et <code>pages.image_id</code>. Le total est exact, et la liste rendue bornée à 50.</p><p><strong>9. Des routes de gestion et deux routes publiques.</strong></p><ul><li>Gestion, sous la session : <code>GET /media</code> (paginé, filtres <code>kind</code>, <code>q</code>, <code>missing_alt</code>), <code>POST</code>, <code>GET</code>, <code>PATCH</code>, <code>DELETE /media/{id}</code>, <code>GET /media/{id}/usages</code> et <code>GET /media/{id}/file</code> (aperçu). Lire demande <code>content.read</code>. Deux permissions nouvelles : <code>media.write</code> (déposer, rédiger) et <code>media.delete</code>. Le contrat les écrit <code>media:write</code> et <code>media:delete</code>, le catalogue les nomme <code>objet.verbe</code>. Le Core donne <code>media.write</code> à tout rôle qui a <code>content.create</code>, et <code>media.delete</code> à tout rôle qui a <code>content.delete</code>. Un manifeste de plugin peut donner la première, jamais la seconde.</li><li>Publiques, sans session : <code>GET /public/media/{id}/file?organization_id=</code> sert les octets en flux, avec <code>ETag</code> (l&#39;empreinte SHA-256, 304 sur <code>If-None-Match</code>), <code>Cache-Control: public, max-age=31536000, immutable</code>, <code>nosniff</code> et <code>Content-Disposition: inline; filename*=…</code>. <code>GET /public/media?organization_id=&amp;ids=…</code> rend les métadonnées d&#39;au plus cent médias en une requête, les absents ignorés. Un identifiant inconnu ou d&#39;une autre organisation rend le même 404.</li><li><strong>Pas de limitation de débit</strong> sur ces deux routes publiques, pour la raison de <code>/public/files</code> (ADR-0035) : elles sont appelées par le serveur du front, et leurs réponses de fichier sont immuables. Aucune catégorie de l&#39;ADR-0031, toutes comptées par adresse, ne conviendrait.</li></ul><p><strong>10. Un média est public par nature.</strong> Qui connaît son identifiant lit ses octets. Un document confidentiel n&#39;a pas sa place dans la médiathèque, et un fichier lié à une personne relève de l&#39;ADR-0017.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Faire passer la médiathèque par <code>personal_files</code></strong></td><td>L&#39;ADR-0017 l&#39;exclut : un visuel n&#39;est lié à personne. Les deux familles auraient partagé racine, sauvegarde et exposition, et la règle « seul le porteur lit son fichier » n&#39;a pas de sens pour une image publique.</td></tr><tr><td><strong>Une médiathèque par site</strong></td><td>Chaque site provisionné aurait recopié chaque fichier, et une correction d&#39;alternative aurait dû être faite autant de fois. Le modèle de site déclarait déjà un partage par référence.</td></tr><tr><td><strong>Miniatures produites par Pillow</strong></td><td>Une dépendance native de plus, un temps de traitement au dépôt et un stockage multiplié, pour un besoin que les proxys d&#39;image et les fronts savent couvrir. Décision du Product Owner.</td></tr><tr><td><strong>Refuser le SVG</strong></td><td>Les logos et pictogrammes des collectivités sont très souvent en SVG. Le servir isolé et refuser les entités suffit, sans analyseur XML.</td></tr><tr><td><strong>Parser le SVG avec <code>xml.etree</code></strong></td><td>Vulnérable à l&#39;expansion d&#39;entités, sans <code>defusedxml</code> dans le projet. Une reconnaissance textuelle bornée de l&#39;élément racine suffit à décider du type.</td></tr><tr><td><strong>Clé étrangère des contenus vers <code>media_assets</code></strong></td><td>Un média est cité dans du JSONB, sous n&#39;importe quel nom de champ et à n&#39;importe quelle profondeur. Aucune contrainte de base ne peut le suivre. La vérification à l&#39;écriture et le refus de suppression tiennent le même rôle, comme pour les relations entre enregistrements.</td></tr><tr><td><strong>Chercher les usages par un parcours des schémas</strong></td><td>Il faudrait connaître chaque schéma et chaque manifeste de bloc, y compris ceux d&#39;un plugin retiré depuis. Un UUID v4 ne se rencontre pas par hasard : la recherche de chaîne ne peut rien manquer.</td></tr><tr><td><strong>Limiter le débit des routes publiques</strong></td><td>Elles sont appelées par le serveur du front, depuis une seule adresse : une limite par adresse épuiserait le crédit de tous les visiteurs réunis (même raisonnement que l&#39;ADR-0035).</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Un identifiant inventé ne passe plus pour un média, dans un enregistrement comme dans une page.</li><li>Une image a une alternative, une légende et un crédit, traduits, corrigés une fois pour tous les contenus qui la citent. Les images sans alternative se listent.</li><li>Un média cité ne disparaît pas sous un contenu publié.</li><li>Les octets se servent en flux et se mettent en cache sans limite de durée. Un SVG ne peut rien exécuter à l&#39;origine de l&#39;API.</li><li>L&#39;action de l&#39;ADR-0017 est close : la médiathèque ne passe pas par <code>personal_files</code>.</li></ul><p><strong>Négatives</strong></p><ul><li>Des contenus existants citent des UUID qui ne désignent rien. Ils restent lisibles, mais leur prochaine écriture demandera de choisir un vrai média.</li><li>La recherche des usages parcourt le JSONB converti en texte de toute l&#39;organisation, sans index. C&#39;est acceptable à l&#39;échelle d&#39;une collectivité, et c&#39;est à mesurer avant d&#39;y ajouter un index trigramme (ADR-0016 : pas d&#39;optimisation sans mesure).</li><li><code>pages.image_id</code> est lu par les usages, mais pas vérifié à l&#39;écriture de la page.</li><li>Supprimer une organisation efface ses lignes <code>media_assets</code> en cascade, mais laisse les octets sur le disque. C&#39;est le même écart que pour les fichiers personnels (ADR-0038).</li><li>Le dépôt lit le fichier entier en mémoire avant de l&#39;écrire, dans la limite de <code>MEDIA_UPLOAD_MAX_MB</code>. Seule la relecture est en flux.</li><li><code>MEDIA_ROOT</code> est un volume de plus à sauvegarder, avec la base : une ligne sans ses octets est un média perdu.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Socle API : table <code>media_assets</code> (migration <code>0034</code>), dépôt <code>app/storage/media_files.py</code>, service <code>app/media/</code>, routes <code>app/api/media.py</code> et <code>app/api/public_media.py</code>, validation des références dans les routes d&#39;enregistrement et de page, permissions <code>media.write</code> et <code>media.delete</code>, réglages <code>MEDIA_ROOT</code> et <code>MEDIA_UPLOAD_MAX_MB</code> vérifiés au démarrage — recette <code>apps/api/tests/test_mediatheque.py</code>.</li><li>[x] Écran Médiathèque et sélecteur visuel du back-office, contre le même contrat d&#39;API — livrés dans le même lot : <code>apps/admin/pages/mediatheque/</code> (liste filtrable, dépôt, fiche, traductions, usages, suppression refusée tant qu&#39;un média sert), <code>apps/admin/components/media/MediaPicker.vue</code> (dialogue modal natif) branché dans les champs <code>media</code>, <code>media_gallery</code>, <code>file</code>, <code>audio</code> et dans le bloc Média, relais BFF <code>apps/admin/server/api/media/</code> (dépôt relayé en flux), commandes réservées à <code>media.write</code>/<code>media.delete</code> ; <code>npm run lint</code>, <code>typecheck</code> et <code>build</code> passent.</li><li>[x] Lot 2 : texte alternatif proposé par l&#39;IA appliqué au média, image de remplacement par type de contenu, image de partage Open Graph (audit SEO, S12), enclosures RSS, extraction documentaire pour la recherche (clé étrangère de <code>search_index.document_id</code>), expansion des médias dans <code>/public/resolve</code> — livré le 23/09/2026 par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0042-mediatheque-branchements">ADR-0042</a>, recettes <code>tests/test_mediatheque_alt_ia.py</code> et <code>tests/test_mediatheque_surfaces.py</code>. <strong>Sauf l&#39;extraction documentaire</strong>, reportée : elle devient une action de l&#39;ADR-0042.</li><li>[x] Vérifier <code>pages.image_id</code> à l&#39;écriture d&#39;une page, comme les blocs — fait par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0042-mediatheque-branchements">ADR-0042</a> (<code>app/api/pages.py:_check_page_image</code>, 422 à la création et à la modification ; recette <code>tests/test_mediatheque_surfaces.py</code>).</li><li>[x] Effacer les octets des médias à la suppression d&#39;une organisation : la cascade n&#39;emporte que les lignes. <strong>Close le 28/09/2026 par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0058-cloture-d-une-organisation">ADR-0058</a></strong> : la clôture d&#39;une organisation efface les octets avant les lignes (<code>app/cli/organization_closure.py</code>, <code>tests/test_cloture_d_une_organisation.py</code>), et le balayage de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0060-balayage-des-fichiers-orphelins">ADR-0060</a> rattrape les orphelins.</li><li>[x] Accepter la vidéo quand la route de fichier saura servir les requêtes <code>Range</code> — fait le 23/09/2026 par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0044-video-depot-en-flux-et-sous-titres">ADR-0044</a> : mp4 et webm, <code>Range</code> sur les routes de fichier, dépôt en flux (ce qui lève aussi la négative « le dépôt lit le fichier entier en mémoire »), sous-titres et transcription ; recettes <code>tests/test_mediatheque_video.py</code> et <code>tests/test_mediatheque_sous_titres.py</code>.</li></ul>',32)])])}const g=t(n,[["render",o]]);export{m as __pageData,g as default};
